import pandas as pd

def recommend_friends(listens: pd.DataFrame, friendship: pd.DataFrame) -> pd.DataFrame:
    m = pd.merge(listens, listens, on=['day', 'song_id'], suffixes=('_1', '_2'))
    m = m[m['user_id_1'] != m['user_id_2']]
    g = m.groupby(['user_id_1', 'user_id_2', 'day'])['song_id'].nunique().reset_index()
    qual = g[g['song_id'] >= 3][['user_id_1', 'user_id_2']].drop_duplicates()

    friends = set()
    for _, row in friendship.iterrows():
        friends.add((row['user1_id'], row['user2_id']))
        friends.add((row['user2_id'], row['user1_id']))

    res = []
    for _, row in qual.iterrows():
        u1, u2 = row['user_id_1'], row['user_id_2']
        if (u1, u2) not in friends:
            res.append({'user_id': u1, 'recommended_id': u2})

    if not res:
        return pd.DataFrame(columns=['user_id', 'recommended_id'])
    return pd.DataFrame(res).drop_duplicates()
